-- calc_wallpaper_designs_name
-- Field: WallpaperDesigns.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_wallpaper_designs_name(p_wallpaper_design_id TEXT)
RETURNS TEXT AS $$
  SELECT (REPLACE(LOWER((SELECT NULLIF(display_name, '') FROM wallpaper_designs WHERE wallpaper_design_id = p_wallpaper_design_id)), ' ', '-'))::text;
$$ LANGUAGE sql STABLE;

